#define INV_LERP(a, b, x) (((x) - (a)) / ((b) - (a)))
#define OSCILLATE(t) ((sin((t) * (3.1415927 / 2.0)) * 0.5) + 0.5)

float LerpTri(float a, float b, float c, float t)
{
    if (t < 0.5)
        return mix(a, b, INV_LERP(0.0, 0.5, t));
    else
        return mix(b, c, INV_LERP(0.5, 1.0, t));
}
float LerpExp(float eMax, float t)
{
    return LerpTri(1.0/eMax, 1.0, eMax, t);
}

//Taken from IQ
vec3 HsvToRgb(in vec3 c)
{
    vec3 rgb = clamp( abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );

	rgb = rgb*rgb*(3.0-2.0*rgb); // cubic smoothing	

	return c.z * mix( vec3(1.0), rgb, c.y);
}
//Source: https://gist.github.com/sugi-cho/6a01cae436acddd72bdf
vec3 RgbToHsv(vec3 c){
	vec4 K=vec4(0.,-1./3.,2./3.,-1.),
	     p=mix(vec4(c.bg ,K.wz),vec4(c.gb,K.xy ),step(c.b,c.g)),
	     q=mix(vec4(p.xyw,c.r ),vec4(c.r ,p.yzx),step(p.x,c.r));
	float d=q.x-min(q.w,q.y),
	      e=1e-10;
	return vec3(abs(q.z+(q.w-q.y)/(6.*d+e)),d/(q.x+e),q.x);
}


///////////////////////////////////////////////

vec4 Noise(vec2 uv) { return textureLod(iChannel0, uv, 0.0); }
vec4 NoiseSnapped(vec2 uv) { return textureLod(iChannel2, uv, 0.0); }

const float NoiseLevelAngle = 2.985;
const mat2 NoiseLevelTransform = mat2(sin(NoiseLevelAngle), cos(NoiseLevelAngle), cos(NoiseLevelAngle), -sin(NoiseLevelAngle));

#define IMPL_OCTAVE_NOISE_START \
        uv += (seed * 0.01);   \
        float maxWeight = 0.0,   \
              weight = 1.0,   \
              scale = 1.0;   \
        vec4 sum = vec4(0.0);   \
   \
        for (int i = 0; i < nOctaves; ++i) {  \
            vec2 pos = uv;    \
            float maxPossible = weight

#define IMPL_OCTAVE_NOISE_MIDDLE   \
            vec4 n = Noise(pos * scale)

#define IMPL_OCTAVE_NOISE_END \
            sum += n * weight;    \
            maxWeight += maxPossible;   \
       \
            weight /= persistence;   \
            scale *= persistence;   \
       \
            uv *= NoiseLevelTransform;   \
            uv += 1.521;   \
        }    \
        vec4 result = sum / max(maxWeight, 0.0000001)

vec4 MultiNoise(vec2 uv, int nOctaves, float persistence, float seed)
{
    IMPL_OCTAVE_NOISE_START;
    IMPL_OCTAVE_NOISE_MIDDLE;
    IMPL_OCTAVE_NOISE_END;
    return result;
}
vec4 MultiNoiseRidge(vec2 uv, int nOctaves, float persistence, float seed)
{
    IMPL_OCTAVE_NOISE_START;
    IMPL_OCTAVE_NOISE_MIDDLE;
    n = 2.0 * abs(n - 0.5);
    IMPL_OCTAVE_NOISE_END;
    return result;
}


///////////////////////////////////////////////

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.x;
    uv *= 1.0 + pow(OSCILLATE(iTime), 2.0);

    float t = iTime * 0.1;
    vec2 domainWarp = MultiNoise(t/20.0 + uv/512.0, 8, 1.3, 0.8888).rg;
    domainWarp *= 0.1;

    vec4 n1 = MultiNoiseRidge(uv/16.0 + t/40.0 + domainWarp, 4, 3.0, 0.234);
    vec4 n10 = 2.0 * abs(n1 - 0.5);
    vec3 n11 = RgbToHsv(n1.rgb),
         n12 = HsvToRgb(n10.rgb);
    vec3 n13 = pow(n12.rgb, vec3(max(0.00001,
        LerpExp(5.0,
                1.0 - n1.a)
    )));
    float finalNoise = min(n13.g, max(n13.r, n13.b));

    vec2 gradientLookup = vec2(pow(finalNoise, 0.5)*0.4 + 0.45);
    vec3 gradientColor = textureLod(iChannel1, gradientLookup, 0.0).rgb;
    gradientColor = pow(gradientColor, vec3(3.5));

    fragColor.rgb = gradientColor;
}
